        strip_http_url(&self.api_endpoint, "tunnel.api_endpoint")?;
        require_env_name(&self.enable_token_env, "tunnel.enable_token_env")?;
        validate_loopback_bind(&self.access_bind, "tunnel.access_bind")?;
        Ok(())
    }

