/// Replace names and list records from a tags probe.
pub fn update_models_from_records(
    &self,
    id: &NodeId,
    records: impl IntoIterator<Item = (impl AsRef<str>, TagRecord)>,
) {
    let Some(node) = self.node(id) else {
